1	// Acceptance tests for the change request:
2	//   "Let me narrow that list to one stage. For example only the ones I have sent."
3	//
4	// The all-invoices page (invoices-page, at /invoices) lists every invoice from every project across
5	// all three stages (DRAFT / SENT / PAID). This change adds a control (invoice-status-filter) that
6	// narrows that list to ONE stage: pick a stage and only the invoices at that stage remain — the rest
7	// are hidden. With nothing picked (the default) every invoice is still shown, exactly as before, so
8	// this is a pure narrowing on top of the existing list.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed; the filter is driven
11	// through the invoice-status-filter control. Seed honours clients: { id, name, email },
12	// projects: { id, clientId, name } and invoices: { id, projectId, amount, status }.
13	//
14	// The filter is a single control (one testid), so it is a <select> of the stages. We do not assume
15	// the casing of its option labels or values: for a wanted stage we locate the option whose visible
16	// text OR value matches the stage case-insensitively and select it by its own value, and to clear we
17	// select the all-stages option (value === '' or an "all" label). So a correct implementation passes
18	// whether it renders stages as 'SENT'/'Sent' and whatever value it carries. Status cells are asserted
19	// case-insensitively (/^sent$/i etc.) to match how the other invoice-stage tests assert status.
20	//
21	// The fixture puts invoices at every stage, with TWO at SENT across two different projects — so
22	// narrowing to "sent" must keep a SET of invoices (not a single hard-coded row) and drop the draft
23	// and the paid one. Narrowing to DRAFT and to PAID in turn proves the control reads the chosen stage
24	// rather than always filtering to one stage. This SHOULD FAIL before the change: there is no
25	// invoice-status-filter on the invoices page today.
26	import { test, expect, type Page } from '@playwright/test';
27	import { resetAndSeed } from '../support/seed';
28	
29	// Invoices at every stage. ids 2 and 4 are both SENT (and sit under different projects), so a genuine
30	// "narrow to sent" keeps both while hiding the DRAFT (1) and the PAID (3).
31	const FIXTURE = {
32	  clients: [
33	    { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
34	    { id: 2, name: 'Globex', email: 'hello@globex.example' },
35	  ],
36	  projects: [
37	    { id: 1, clientId: 1, name: 'Website redesign' },
38	    { id: 2, clientId: 2, name: 'Warehouse automation' },
39	  ],
40	  invoices: [
41	    { id: 1, projectId: 1, amount: 120, status: 'DRAFT' },
42	    { id: 2, projectId: 1, amount: 300, status: 'SENT' },
43	    { id: 3, projectId: 2, amount: 999, status: 'PAID' },
44	    { id: 4, projectId: 2, amount: 450, status: 'SENT' },
45	  ],
46	};
47	
48	// The <option> value whose visible text OR value matches `stage` (case-insensitive). Selecting by the
49	// option's own value keeps us agnostic to the label/value casing the feature chose.
50	async function optionValueFor(page: Page, stage: RegExp): Promise<string> {
51	  const value = await page
52	    .getByTestId('invoice-status-filter')
53	    .locator('option')
54	    .evaluateAll((opts, src) => {
55	      const re = new RegExp(src as string, 'i');
56	      const match = (opts as HTMLOptionElement[]).find(
57	        (o) => re.test((o.textContent ?? '').trim()) || re.test(o.value),
58	      );
59	      return match ? match.value : null;
60	    }, stage.source);
61	  if (value === null) {
62	    throw new Error(`invoice-status-filter has no option matching ${stage}`);
63	  }
64	  return value;
65	}
66	
67	// Narrow the list to a single stage through the control.
68	async function narrowTo(page: Page, stage: RegExp): Promise<void> {
69	  await page.getByTestId('invoice-status-filter').selectOption(await optionValueFor(page, stage));
70	}
71	
72	// The "show every stage" option: an empty value by convention, or an option labelled "all".
73	async function showAllStages(page: Page): Promise<void> {
74	  const value = await page
75	    .getByTestId('invoice-status-filter')
76	    .locator('option')
77	    .evaluateAll((opts) => {
78	      const match = (opts as HTMLOptionElement[]).find(
79	        (o) => o.value === '' || /all/i.test((o.textContent ?? '').trim()),
80	      );
81	      return match ? match.value : null;
82	    });
83	  if (value === null) {
84	    throw new Error('invoice-status-filter has no "all stages" option');
85	  }
86	  await page.getByTestId('invoice-status-filter').selectOption(value);
87	}
88	
89	test.describe('narrow all-invoices to one stage', () => {
90	  test.beforeEach(async () => {
91	    await resetAndSeed(FIXTURE);
92	  });
93	
94	  test('with nothing picked, the filter is present and every invoice is shown', async ({ page }) => {
95	    await page.goto('/invoices');
96	
97	    await expect(page.getByTestId('invoices-page')).toBeVisible();
98	    await expect(page.getByTestId('invoice-status-filter')).toBeVisible();
99	
100	    // Default view: all four invoices, across both projects and all stages.
101	    await expect(page.getByTestId('invoice-row-1')).toBeVisible();
102	    await expect(page.getByTestId('invoice-row-2')).toBeVisible();
103	    await expect(page.getByTestId('invoice-row-3')).toBeVisible();
104	    await expect(page.getByTestId('invoice-row-4')).toBeVisible();
105	    await expect(page.locator('[data-testid^="invoice-row-"]')).toHaveCount(4);
106	  });
107	
108	  test('narrowing to SENT keeps only the sent invoices', async ({ page }) => {
109	    await page.goto('/invoices');
110	    await expect(page.getByTestId('invoice-row-1')).toBeVisible();
111	
112	    // "Only the ones I have sent."
113	    await narrowTo(page, /^sent$/);
114	
115	    // The two SENT invoices (2 and 4) remain; the DRAFT (1) and the PAID (3) are gone.
